<?php namespace App\Controllers\Api; use App\Models\OrderModel;
class AdminOrders extends BaseApi {
 public function index(){if(!$this->adminCan('orders','view'))return $this->ok(['message'=>'Forbidden'],403);$db=db_connect();$rows=(new OrderModel())->orderBy('id','DESC')->findAll();foreach($rows as &$r)$r['items']=$db->table('order_items')->where('order_id',$r['id'])->get()->getResultArray();return $this->ok(['data'=>$rows]);}
 public function update($id=null){if(!$this->adminCan('orders','edit'))return $this->ok(['message'=>'Forbidden'],403);$d=$this->json();$allowed=['Pending','Confirmed','Packed','Shipped','Delivered','Cancelled','Returned'];$row=[];if(isset($d['status'])){if(!in_array($d['status'],$allowed,true))return $this->ok(['message'=>'Invalid status'],422);$row['status']=$d['status'];}foreach(['tracking_number','tracking_url','payment_status'] as $k)if(array_key_exists($k,$d))$row[$k]=$d[$k];(new OrderModel())->update((int)$id,$row);return $this->ok(['message'=>'Order updated']);}
 public function invoice($id=null){if(!$this->adminCan('orders','view'))return $this->ok(['message'=>'Forbidden'],403);$db=db_connect();$o=(new OrderModel())->find((int)$id);if(!$o)return $this->ok(['message'=>'Order not found'],404);if(empty($o['invoice_number'])){$inv='INV-'.date('Y').'-'.str_pad((string)$o['id'],6,'0',STR_PAD_LEFT);$db->table('orders')->where('id',$o['id'])->update(['invoice_number'=>$inv]);$o['invoice_number']=$inv;}$items=$db->table('order_items')->where('order_id',$o['id'])->get()->getResultArray();$settings=[];foreach($db->table('store_settings')->get()->getResultArray() as $r)$settings[$r['setting_key']]=$r['setting_value'];return $this->ok(['data'=>['o'=>$o,'items'=>$items,'settings'=>$settings]]);}
}
